package com.gmail.manhle240406.project.community;
import android.content.*;import androidx.test.core.app.ActivityScenario;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.uiautomator.*;import com.gmail.manhle240406.project.*;import com.gmail.manhle240406.project.R;import com.google.firebase.FirebaseApp;import com.google.firebase.auth.*;import com.google.android.gms.tasks.Tasks;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import java.util.*;import static org.junit.Assert.*;import static androidx.test.espresso.Espresso.*;import static androidx.test.espresso.action.ViewActions.*;import static androidx.test.espresso.matcher.ViewMatchers.*;
@RunWith(AndroidJUnit4.class) public class Oc3DirectLiveTest {
 private JSONObject call(String token,String op,JSONObject data,int status)throws Exception{java.net.HttpURLConnection c=(java.net.HttpURLConnection)new java.net.URL("https://asia-east2-aniloveproject.cloudfunctions.net/mediaApi/"+op).openConnection();c.setRequestMethod("POST");c.setConnectTimeout(30000);c.setReadTimeout(30000);c.setRequestProperty("Authorization","Bearer "+token);c.setRequestProperty("Content-Type","application/json");c.setDoOutput(true);try(java.io.OutputStream out=c.getOutputStream()){out.write(data.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));}int code=c.getResponseCode();java.io.InputStream in=code<400?c.getInputStream():c.getErrorStream();String text=new String(in.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);c.disconnect();assertEquals(text,status,code);return new JSONObject(text);}
 private JSONObject command(String id,String text)throws Exception{return new JSONObject().put("conversationId",id).put("operationId",UUID.randomUUID().toString()).put("body",text);}
 @Test public void primaryUserFindsDisposablePeerSendsReceivesAndBlocks()throws Exception{Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();String primary=FirebaseAuth.getInstance().getUid();assertNotNull(primary);JSONObject fixture=new JSONObject(java.nio.file.Files.readString(new java.io.File(c.getExternalFilesDir(null),"oc3-direct-fixture.json").toPath()));JSONObject beta=fixture.getJSONArray("users").getJSONObject(1);FirebaseApp secondary=FirebaseApp.initializeApp(c,FirebaseApp.getInstance().getOptions(),"oc3-native-"+UUID.randomUUID());UiDevice device=UiDevice.getInstance(InstrumentationRegistry.getInstrumentation());try{FirebaseAuth auth=FirebaseAuth.getInstance(secondary);Tasks.await(auth.signInWithEmailAndPassword(beta.getString("email"),beta.getString("password")),30,java.util.concurrent.TimeUnit.SECONDS);String token=Tasks.await(auth.getCurrentUser().getIdToken(false),30,java.util.concurrent.TimeUnit.SECONDS).getToken();try(ActivityScenario<MainActivity> scenario=ActivityScenario.launch(MainActivity.class)){System.out.println("OC3_STAGE main-launched");scenario.onActivity(a->a.navigate("chat"));assertTrue(device.wait(Until.hasObject(By.res(c.getPackageName(),"oc3_chat_new")),30000));System.out.println("OC3_STAGE inbox-ready");onView(withId(R.id.oc3_chat_new)).perform(click());onView(isAssignableFrom(com.google.android.material.textfield.TextInputEditText.class)).perform(replaceText(beta.getString("name")),androidx.test.espresso.action.ViewActions.closeSoftKeyboard());onView(withText(R.string.oc3_find)).perform(click());assertTrue(device.wait(Until.hasObject(By.text(beta.getString("name"))),30000));onView(org.hamcrest.Matchers.allOf(withText(beta.getString("name")),isAssignableFrom(com.google.android.material.button.MaterialButton.class))).perform(click());assertTrue(device.wait(Until.hasObject(By.res(c.getPackageName(),"oc3_chat_input").enabled(true)),30000));System.out.println("OC3_STAGE thread-open");onView(withId(R.id.oc3_chat_input)).perform(replaceText("QA OC3 native hello"),androidx.test.espresso.action.ViewActions.closeSoftKeyboard());onView(withId(R.id.oc3_chat_send)).perform(click());assertTrue(device.wait(Until.hasObject(By.text("QA OC3 native hello")),30000));System.out.println("OC3_STAGE native-send-visible");JSONArray inbox=call(token,"directInbox",new JSONObject().put("after",JSONObject.NULL),200).getJSONArray("rows");String id=null;for(int i=0;i<inbox.length();i++)if(primary.equals(inbox.getJSONObject(i).getString("peerUid")))id=inbox.getJSONObject(i).getString("conversationId");assertNotNull(id);call(token,"directSend",command(id,"QA OC3 native reply"),200);System.out.println("OC3_STAGE reply-sent");device.findObject(By.res(c.getPackageName(),"oc3_chat_refresh")).swipe(Direction.DOWN,.6f);assertTrue(device.wait(Until.hasObject(By.text("QA OC3 native reply")),35000));System.out.println("OC3_STAGE reply-visible");device.findObject(By.text(c.getString(R.string.oc3_block))).click();assertTrue(device.wait(Until.hasObject(By.res("android","button1")),5000));device.findObject(By.res("android","button1")).click();assertTrue(device.wait(Until.hasObject(By.text(c.getString(R.string.oc3_unblock))),30000));System.out.println("OC3_STAGE blocked");call(token,"directSend",command(id,"Blocked message"),403);device.findObject(By.text(c.getString(R.string.oc3_unblock))).click();assertTrue(device.wait(Until.hasObject(By.res("android","button1")),5000));device.findObject(By.res("android","button1")).click();assertTrue(device.wait(Until.hasObject(By.text(c.getString(R.string.oc3_block))),30000));call(token,"directSend",command(id,"QA OC3 unblocked native"),200);System.out.println("OC3_STAGE unblocked");device.takeScreenshot(new java.io.File(c.getExternalFilesDir(null),"oc3-direct-thread.png"));assertEquals(primary,FirebaseAuth.getInstance().getUid());}}finally{secondary.delete();assertEquals(primary,FirebaseAuth.getInstance().getUid());}}
}
